declare_lint_rule! {
    /// Disallow selectors with too many class selectors.
    ///
    /// Selectors that chain many class selectors together are harder to read,
    /// override, and reuse. This rule flags individual selectors that contain
    /// more class selectors than the configured maximum.
    ///
    /// Class selectors are counted per individual selector, including class
    /// selectors nested inside pseudo-class functions such as `:not()`, `:is()`,
    /// `:has()`, and `:nth-child(... of ...)`. Each selector in a comma-separated
    /// list is evaluated independently, and nested selectors are evaluated on
    /// their own rather than combined with their parent's class count.
    ///
    /// This rule does nothing unless the `maxClasses` option is set.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// The following example will show a diagnostic when `maxClasses` is set to 1:
    ///
    /// ```json,options
    /// {
    ///     "options": {
    ///        "maxClasses": 1
    ///     }
    /// }
    /// ```
    /// ```css,expect_diagnostic,use_options
    /// .a.b {
    ///   color: red;
    /// }
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css,use_options
    /// .a {
    ///   color: red;
    /// }
    /// ```
    ///
    /// ## Options
    ///
    /// ### `maxClasses`
    ///
    /// This option sets the maximum number of class selectors allowed in a single
    /// selector. When it is not set, the rule does not report any diagnostics.
    ///
    pub NoExcessiveSelectorClasses {
        version: "next",
        name: "noExcessiveSelectorClasses",
        language: "css",
        recommended: false,
        severity: Severity::Warning,
    }
}

impl Rule for NoExcessiveSelectorClasses {
    type Query = Ast<AnyCssSelector>;
    type State = usize;
    type Signals = Option<Self::State>;
    type Options = NoExcessiveSelectorClassesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        // The rule is inert unless a maximum is configured.
        let max_classes = ctx.options().max_classes?;

        let selector = ctx.query();

        // Only evaluate top-level selectors of a rule's prelude. Selectors nested
        // inside another selector (e.g. the sides of a complex selector) or inside
        // pseudo-class function arguments are counted as part of their enclosing
        // top-level selector rather than checked on their own.
        if !is_top_level_selector(selector) {
            return None;
        }

        // SCSS selectors that contain an interpolation are dynamic, so we can't
        // reliably reason about them.
        if has_interpolation(selector) {
            return None;
        }

        let class_count = count_class_selectors(selector);

        if class_count > usize::from(max_classes) {
            Some(class_count)
        } else {
            None
        }
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let selector = ctx.query();
        let max_classes = ctx.options().max_classes.unwrap_or_default();
        let found = *state;

        let message = if max_classes == 1 {
            markup! {
                "Expected this selector to have no more than "{max_classes}" class selector, but found "{found}"."
            }
        } else {
            markup! {
                "Expected this selector to have no more than "{max_classes}" class selectors, but found "{found}"."
            }
        };

        Some(
            RuleDiagnostic::new(rule_category!(), selector.range(), message)
                .note(markup! {
                    "Selectors with too many chained classes are harder to read, override, and reuse."
                })
                .note(markup! {
                    "Reduce the number of class selectors in this selector, or split it into simpler selectors."
                }),
        )
    }
}

/// Returns `true` if the selector is a top-level selector of a rule's prelude,
/// i.e. a direct item of a `CssSelectorList` belonging to a qualified rule or a
/// `CssRelativeSelector` belonging to a nested qualified rule.
fn is_top_level_selector(selector: &AnyCssSelector) -> bool {
    let Some(parent) = selector.syntax().parent() else {
        return false;
    };

    match parent.kind() {
        CssSyntaxKind::CSS_SELECTOR_LIST => parent
            .parent()
            .is_some_and(|grand_parent| grand_parent.kind() == CssSyntaxKind::CSS_QUALIFIED_RULE),
        CssSyntaxKind::CSS_RELATIVE_SELECTOR => parent
            .parent()
            .and_then(|list| list.parent())
            .is_some_and(|owner| owner.kind() == CssSyntaxKind::CSS_NESTED_QUALIFIED_RULE),
        _ => false,
    }
}

/// Counts every class selector within the given selector, including those nested
/// inside pseudo-class function arguments.
fn count_class_selectors(selector: &AnyCssSelector) -> usize {
    selector
        .syntax()
        .descendants()
        .filter(|node| node.kind() == CssSyntaxKind::CSS_CLASS_SELECTOR)
        .count()
}

/// Returns `true` if the selector contains an SCSS interpolation anywhere.
fn has_interpolation(selector: &AnyCssSelector) -> bool {
    selector.syntax().descendants().any(|node| {
        matches!(
            node.kind(),
            CssSyntaxKind::SCSS_INTERPOLATION
                | CssSyntaxKind::SCSS_INTERPOLATED_IDENTIFIER
                | CssSyntaxKind::SCSS_INTERPOLATED_STRING
        )
    })
}
